#!/usr/bin/env bash
set -euo pipefail
MODE="${1:-DRY_RUN}"; PS="${2:-}"; PD="${3:-}"; SUMMARY="${GITHUB_STEP_SUMMARY:-/dev/stdout}"
classify(){ local s="origin/$1" d="origin/$2" c so do_; c="$(git diff --name-only "$s" "$d"|sed '/^$/d'|wc -l|tr -d ' ')"; so="$(git rev-list --count "$d..$s")"; do_="$(git rev-list --count "$s..$d")"; if [ "$c" -eq 0 ]; then echo OK; elif [ "$so" -gt 0 ] && [ "$do_" -eq 0 ]; then echo PROMOTION_AVAILABLE; else echo BLOCKED; fi; }
if [ "$MODE" = PAIR ]; then classify "$PS" "$PD"; exit 0; fi
detail(){ local src="$1" dst="$2" label="$3" s="origin/$1" d="origin/$2" c so do_ st rel f m e ci; c="$(git diff --name-only "$s" "$d"|sed '/^$/d'|wc -l|tr -d ' ')"; so="$(git rev-list --count "$d..$s")"; do_="$(git rev-list --count "$s..$d")"; st="$(classify "$src" "$dst")"; if [ "$c" -eq 0 ]; then if [ "$so" -eq 0 ]&&[ "$do_" -eq 0 ];then rel=IDENTICAL;elif [ "$so" -eq 0 ];then rel=DESTINATION_AHEAD_HISTORY_ONLY;elif [ "$do_" -eq 0 ];then rel=SOURCE_AHEAD_HISTORY_ONLY;else rel=SYNCED_CONTENT_DIFFERENT_HISTORY;fi; elif [ "$st" = PROMOTION_AVAILABLE ];then rel=SOURCE_AHEAD;elif [ "$so" -eq 0 ];then rel=DESTINATION_AHEAD_WITH_CHANGES;else rel=DIVERGED;fi; f="$(git diff --name-only "$d" "$s" -- index.html app.js styles.css config.js sw.js version.json manifest.webmanifest assets/|sed '/^$/d'|wc -l|tr -d ' ')"; m="$(git diff --name-only "$d" "$s" -- supabase/migrations/|sed '/^$/d'|wc -l|tr -d ' ')"; e="$(git diff --name-only "$d" "$s" -- supabase/functions/|sed '/^$/d'|wc -l|tr -d ' ')"; ci="$(git diff --name-only "$d" "$s" -- .github/workflows/ scripts/release/|sed '/^$/d'|wc -l|tr -d ' ')"; { echo "### $label";echo;echo "| Item | Value |";echo "|---|---|";echo "| Status | **$st** |";echo "| Git relation | \`$rel\` |";echo "| Source-only commits | $so |";echo "| Destination-only commits | $do_ |";echo "| Content differences | $c files |";echo "| Frontend pending | $f |";echo "| Migrations pending | $m |";echo "| Edge Functions pending | $e |";echo "| CI/CD pending | $ci |";echo; }>>"$SUMMARY"; if [ "$c" -gt 0 ];then { echo "<details><summary>Files different</summary>";echo;echo '```text';git diff --name-status "$d" "$s";echo '```';echo "</details>";echo; }>>"$SUMMARY";fi; echo "$st"; }
{ echo "# Yebenes environment alignment";echo;echo "**Mode:** \`$MODE\`";echo; }>>"$SUMMARY"
a="$(detail develop test 'DEVELOP -> TEST')"; b="$(detail test main 'TEST -> DEMO (main)')"
{ echo "## Overall result";echo;if [ "$a" = BLOCKED ]||[ "$b" = BLOCKED ];then echo "❌ **Environment drift requires attention.**";elif [ "$a" = PROMOTION_AVAILABLE ]||[ "$b" = PROMOTION_AVAILABLE ];then echo "🟡 **Changes are pending promotion.**";else echo "✅ **All three environments are aligned in content.**";fi; }>>"$SUMMARY"
